digraph G {
  rankdir=LR;
  A [label="Start"]
  B [label="End"]
  A -> B;
}

digraph StateMachine {
  rankdir=LR;
  node [shape = circle];
  S0 -> S1 [label="Event A"];
  S1 -> S2 [label="Event B"];
  S2 -> S0 [label="Event C"];
}

graph Network {
  layout=neato;
  node [shape=box, style=filled, color=lightblue];
  Router1 -- ServerA;
  Router1 -- ServerB;
  ServerA -- Database1;
}

digraph DFD {
  rankdir=LR;
  node [shape=box];
  ExternalEntity [shape=rect, label="External Entity"];
  Process1 [shape=circle, label="Process 1"];
  DataStore1 [shape=record, label="Data Store A"];
  ExternalEntity -> Process1 [label="Input Data"];
  Process1 -> DataStore1 [label="Write"];
  DataStore1 -> Process1 [label="Read"];
  Process1 -> ExternalEntity [label="Output Data"];
}

digraph UseCase {
    actor User
    node [shape=ellipse];
    UC1 [label="Execute Function A"];
    UC2 [label="Use Function B"];
    UC3 [label="Generate Report"];
    User -> UC1;
    User -> UC2;
    UC2 -> UC3 [label="<<include>>", style=dashed, arrowhead=open]; 
}

digraph FileSystem {
    node [shape=folder, style=filled, fillcolor=lightyellow];
    edge [arrowhead=none];
    root [label="/"];
    root -> usr;
    root -> home;
    root -> etc;
    usr -> bin;
    usr -> lib;
    usr -> local;
    home -> user1 [label="user1", shape=house, fillcolor=lightblue];
